import React, { useState } from 'react';

interface PhraseGuideProps {
  onBack: () => void;
  onHome: () => void;
}

const PhraseGuide: React.FC<PhraseGuideProps> = ({ onBack, onHome }) => {
  const [selectedCategory, setSelectedCategory] = useState<string>('');

  const phraseCategories = [
    {
      id: 'discount',
      title: '1️⃣ 할인/이벤트 강조',
      phrases: [
        '🔥 오늘만 특가! ~50% 할인',
        '⚡ 플래시 세일 진행중',
        '🎉 신규 고객 20% 할인',
        '💎 VIP 고객 전용 특가',
        '📅 기간 한정 특가',
        '🎁 구매 시 사은품 증정'
      ]
    },
    {
      id: 'review',
      title: '2️⃣ 후기 기반 신뢰 유도',
      phrases: [
        '⭐ 4.8점 고객 만족도',
        '💬 1000+ 후기 보기',
        '👍 베스트 리뷰어 추천',
        '🏆 연속 3년 베스트셀러',
        '💯 만족도 100% 보장',
        '👥 10만 고객이 선택한'
      ]
    },
    {
      id: 'fomo',
      title: '3️⃣ 클릭 유도형 (FOMO)',
      phrases: [
        '⏰ 마감 임박! 재고 소진',
        '🚨 마지막 기회 놓치지 마세요',
        '💥 오늘 하루만! 내일부터 가격 인상',
        '🔥 핫딜 마감 30분 전',
        '⚡ 빠른 구매가 관건!',
        '🎯 한정 수량 선착순'
      ]
    },
    {
      id: 'mypage',
      title: '4️⃣ 마이페이지 배너용',
      phrases: [
        '💝 내가 찜한 그 상품, 오늘 할인 중!',
        '🔥 1년 중 제일 핫해! ~90%',
        '😱 놓치면 후회할 베스트템',
        '📊 이번 달 인기템 TOP5',
        '🎁 나만을 위한 맞춤 추천',
        '⭐ 내 취향 저격 상품 모음'
      ]
    }
  ];

  return (
    <div>
      <div className="card">
        <div className="flex" style={{ alignItems: 'center', marginBottom: '20px' }}>
          <button className="btn btn-secondary" onClick={onBack}>
            ← 뒤로가기
          </button>
          <button className="btn-home" onClick={onHome}>
            🏠 홈
          </button>
          <h2 style={{ marginLeft: '20px', fontSize: '1.6rem', color: '#1e293b' }}>
            📣 잘 먹히는 문구 추천받기
          </h2>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            어떤 분위기의 문구를 찾고 계신가요?
          </h3>

          <div className="grid">
            {phraseCategories.map((category) => (
              <div 
                key={category.id}
                className="card"
                style={{ 
                  cursor: 'pointer',
                  border: selectedCategory === category.id ? '2px solid #3b82f6' : '1px solid #e2e8f0'
                }}
                onClick={() => setSelectedCategory(category.id)}
              >
                <h4 style={{ fontSize: '1.1rem', marginBottom: '10px', color: '#1e293b' }}>
                  {category.title}
                </h4>
                <p style={{ color: '#64748b', fontSize: '0.9rem' }}>
                  {category.id === 'discount' && '할인과 이벤트를 강조하는 문구'}
                  {category.id === 'review' && '고객 후기와 신뢰도를 강조하는 문구'}
                  {category.id === 'fomo' && '긴급성과 한정성을 강조하는 문구'}
                  {category.id === 'mypage' && '개인화된 추천과 맞춤 정보'}
                </p>
              </div>
            ))}
          </div>
        </div>

        {selectedCategory && (
          <div className="mb-20">
            <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
              📝 추천 문구 리스트
            </h3>

            <div className="card">
              <div className="grid">
                {phraseCategories
                  .find(cat => cat.id === selectedCategory)
                  ?.phrases.map((phrase, index) => (
                    <div key={index} className="card" style={{ padding: '15px' }}>
                      <p style={{ 
                        fontSize: '1rem', 
                        color: '#1e293b', 
                        fontWeight: '500',
                        lineHeight: '1.4'
                      }}>
                        {phrase}
                      </p>
                      <button 
                        className="btn btn-secondary" 
                        style={{ 
                          marginTop: '10px', 
                          fontSize: '0.8rem',
                          padding: '6px 12px'
                        }}
                        onClick={() => navigator.clipboard.writeText(phrase)}
                      >
                        복사하기
                      </button>
                    </div>
                  ))}
              </div>
            </div>
          </div>
        )}

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            🔗 예시 문구 (마이페이지 배너용)
          </h3>

          <div className="card">
            <div className="grid">
              {phraseCategories
                .find(cat => cat.id === 'mypage')
                ?.phrases.map((phrase, index) => (
                  <div key={index} className="card" style={{ 
                    padding: '15px',
                    background: '#3b82f6',
                    color: 'white'
                  }}>
                    <p style={{ 
                      fontSize: '1rem', 
                      fontWeight: '500',
                      lineHeight: '1.4'
                    }}>
                      {phrase}
                    </p>
                  </div>
                ))}
            </div>
          </div>
        </div>

        <div className="tip">
          <strong>🗂 전체 문구 리스트를 보고 싶다면</strong><br/>
          → <button className="btn">문구 데이터베이스 전체 보기</button>
        </div>
      </div>
    </div>
  );
};

export default PhraseGuide;
